        setStatus2(`\u{1F94A} S\u1EDBi D\u1EBF: \u0110ang thi \u0111\u1EA5u${config2.benAutoTickle ? " \xB7 t\u1EF1 kh\u1EC1u r\xE2u \u0111\xFAng nh\u1ECBp" : ""} (c\xF2n ${left} l\u1EA7n kh\u1EC1u)`);
        return { finishedArea: false };
